<script setup lang="ts">
import {ref,watch,onMounted,onBeforeUnmount} from 'vue';import {api,ApiError} from '../api';import {useWorkspace,type WorkTab} from '../stores';import Modal from '../components/Modal.vue';
const props=defineProps<{tab:WorkTab}>(),work=useWorkspace();const manual=props.tab.kind==='store-history-editor';const fields=[['store_code','門市代碼',20],['store_name','門市名稱',100],['short_name','簡稱',200],['hr_store_code','人資門市代碼',200],['manager_name','負責人',200]] as const;
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const form=ref<any>({}),store=ref<any>(null),history=ref<any[]>([]),error=ref(''),message=ref(''),loading=ref(false),conflict=ref(false),canSave=ref(false),confirm=ref(false),pendingDelete=ref<any>(null),refill=ref(false);let baseline='',pendingKey='',requestId='',resolver:((ok:boolean)=>void)|null=null;
watch(form,()=>{props.tab.dirty=JSON.stringify(form.value)!==baseline;message.value='';},{deep:true,flush:'sync'});
async function load(preserve=false){loading.value=true;error.value='';try{const d=await api('stores?id='+props.tab.recordId);store.value=d.stores[0];history.value=d.history;canSave.value=d.capabilities.relocate;const next:any={relocation_date:today(),note:''};for(const [key] of fields){next['new_'+key]=store.value[key]||'';if(manual)next['old_'+key]='';}if(manual&&props.tab.payload?.history)for(const k of Object.keys(next))next[k]=props.tab.payload.history[k]||'';if(!preserve){baseline=JSON.stringify(next);form.value=next;props.tab.dirty=false;}conflict.value=false;}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
function answer(ok:boolean){confirm.value=false;resolver?.(ok);resolver=null;}
async function send(operation:string,data:any,expected:string){const key=JSON.stringify({operation,data});if(key!==pendingKey){pendingKey=key;requestId=crypto.randomUUID();}return api('stores',{method:'POST',body:JSON.stringify({operation,data,expected,requestId})});}
async function save(){if(!canSave.value||props.tab.busy||loading.value||conflict.value||(!manual&&!store.value?.is_active))return false;error.value='';for(const prefix of manual?['old_','new_']:['new_'])if(!form.value[prefix+'store_code']?.trim()||!form.value[prefix+'store_name']?.trim()){error.value='請填寫搬遷前後的門市代碼與名稱';return false;}if(!form.value.relocation_date){error.value='請填寫搬遷日期';return false;}if(!manual){if(confirm.value)return false;const ok=await new Promise<boolean>(r=>{resolver=r;confirm.value=true;});if(!ok)return false;}props.tab.busy=true;try{await send(manual?'history-add':'relocate',{...form.value,id:props.tab.recordId},store.value.version);baseline=JSON.stringify(form.value);props.tab.dirty=false;await load(true);message.value=error.value?'已儲存，請重新載入確認最新資料':manual?'歷史沿革已補建，目前門市主檔未變更':'門市搬遷資料與沿革已儲存';if(error.value)conflict.value=true;return true;}catch(e){error.value=(e as Error).message;conflict.value=e instanceof ApiError&&e.status===409&&error.value.includes('其他人');return false;}finally{props.tab.busy=false;}}
function newHistory(record?:any){const tab=work.open('store-history-editor',props.tab.recordId,props.tab.recordId);tab.title='補建沿革 · '+store.value.store_name;if(record)tab.payload={history:record};}
async function deleteHistory(){if(props.tab.busy||!pendingDelete.value)return;const record=pendingDelete.value;props.tab.busy=true;error.value='';try{await send('history-delete',{id:props.tab.recordId,history_id:record.id},record.version);pendingDelete.value=null;await load(true);if(refill.value)newHistory(record);message.value='沿革已刪除，目前門市主檔未變更';}catch(e){error.value=(e as Error).message;pendingDelete.value=null;}finally{props.tab.busy=false;}}
props.tab.save=save;onMounted(()=>load());onBeforeUnmount(()=>{answer(false);delete props.tab.save;});
</script><template><header class="page-heading"><div><p class="eyebrow">組織與門市 / 門市沿革</p><h1>{{manual?'補建歷史沿革':'門市搬遷與沿革'}}</h1><p v-if="store">{{store.store_code}} {{store.store_name}}</p></div><button :disabled="tab.busy||loading||confirm" @click="load(tab.dirty)">{{tab.dirty?'重新載入（保留草稿）':'重新載入'}}</button></header><p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><p v-if="loading" role="status">載入門市沿革…</p><template v-else-if="store"><p class="notice">{{manual?'補建沿革只新增歷史紀錄，不會修改目前門市主檔。':'搬遷會保留原門市 ID、員工與業務資料關聯，更新代碼及名稱並新增一筆歷史紀錄。'}}</p><p v-if="!store.is_active&&!manual" class="muted">已停止門市僅能查看與維護沿革，不能執行搬遷。</p><form v-if="canSave&&(manual||store.is_active)" @submit.prevent="save"><fieldset :disabled="tab.busy||conflict||confirm"><div class="relocation-columns"><section v-for="prefix in (manual?['old_','new_']:['new_'])" :key="prefix"><h2>{{prefix==='old_'?'搬遷前':'搬遷後'}}</h2><label v-for="[key,label,max] in fields" :key="key">{{label}}<input :aria-label="label" v-model="form[prefix+key]" :maxlength="max" :required="key==='store_code'||key==='store_name'"><small v-if="!manual">目前：{{store[key]||'—'}}</small></label></section></div><label>搬遷日期<input type="date" v-model="form.relocation_date" required></label><label>備註說明<textarea v-model="form.note" rows="3" maxlength="5000"></textarea></label></fieldset><div class="dialog-actions"><button class="primary" :disabled="tab.busy||conflict||confirm||!tab.dirty">{{tab.busy?'儲存中…':manual?'儲存歷史沿革':'儲存搬遷'}}</button></div></form><section v-if="!manual" class="history"><header><h2>搬遷歷史（{{history.length}}）</h2><button v-if="canSave" :disabled="tab.busy" @click="newHistory()">補建歷史沿革</button></header><article v-for="h in history" :key="h.id"><h3>{{h.relocation_date}}</h3><dl><div v-for="[key,label] in fields" :key="key"><dt>{{label}}</dt><dd>{{h['old_'+key]||'—'}} → {{h['new_'+key]||'—'}}</dd></div></dl><p class="note">{{h.note||'無備註'}}</p><div class="module-actions" v-if="canSave"><button :disabled="tab.busy" @click="pendingDelete=h;refill=false">刪除沿革</button><button :disabled="tab.busy" @click="pendingDelete=h;refill=true">刪除並帶入重填</button></div></article><p v-if="!history.length" class="muted">尚無搬遷沿革</p></section></template>
<Modal v-if="confirm" title="確認門市搬遷" @cancel="answer(false)"><p>將 {{store.store_code}} {{store.store_name}} 更新為 {{form.new_store_code}} {{form.new_store_name}}。</p><p>搬遷日期：{{form.relocation_date}}。原門市 ID 與業務資料關聯保留。</p><div class="dialog-actions"><button @click="answer(false)">返回編輯</button><button class="primary" @click="answer(true)">確認儲存搬遷</button></div></Modal>
<Modal v-if="pendingDelete" title="確認刪除歷史沿革" :busy="tab.busy" @cancel="pendingDelete=null"><p>刪除 {{pendingDelete.relocation_date}} 的沿革：{{pendingDelete.old_store_code}} → {{pendingDelete.new_store_code}}。</p><p>只刪除歷史，不回復目前門市主檔。{{refill?'刪除後會開啟補建頁帶入原資料，請完成修正與儲存。':''}}</p><div class="dialog-actions"><button :disabled="tab.busy" @click="pendingDelete=null">取消刪除</button><button class="danger" :disabled="tab.busy" @click="deleteHistory">確認刪除沿革</button></div></Modal></template><style scoped>fieldset{padding:0;border:0;min-width:0}form{max-width:1000px}label{display:grid;gap:8px;margin:16px 0}input,textarea{width:100%;min-width:0}textarea{font:inherit;background:var(--surface);color:var(--ink);padding:10px;border:1px solid var(--line)}small{color:var(--muted)}.relocation-columns{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:28px}h2{font-size:18px}.history{margin-top:32px}.history header{display:flex;align-items:center;justify-content:space-between;gap:14px}.history article{padding:20px 0;border-bottom:1px solid var(--line)}.history h3{font-size:16px}.history dl{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}.history dt{font-size:12px;color:var(--muted)}.history dd{margin:6px 0;overflow-wrap:anywhere}.note{white-space:pre-wrap;overflow-wrap:anywhere}</style>
